from PIL import Image
for state in ['initial','reach_step1','pull_probe']:
 m=json.load(open('/app/output/'+state+'/meta.json')); print('\n',state)
 for c in ['left','right','top']:
  im=np.array(Image.open('/app/output/'+state+'/last/'+c+'.jpg')).astype(int);D=np.load('/app/output/'+state+'/depth_'+c+'.npy')[0].astype(float)
  mask=(im[:,:,1]>1.5*im[:,:,0])&(im[:,:,1]>1.3*im[:,:,2])&(im[:,:,1]>100)&(D<3)
  if c in ['left','right']: mask &= (np.indices(mask.shape)[1]>130)&(np.indices(mask.shape)[1]<195)&(np.indices(mask.shape)[0]>35)&(np.indices(mask.shape)[0]<120)
  if c=='top': mask &= (np.indices(mask.shape)[0]>90)&(np.indices(mask.shape)[0]<130)
  ys,xs=np.where(mask)
  print(c,len(xs),'bbox',(xs.min(),xs.max(),ys.min(),ys.max()) if len(xs) else None)
  if len(xs):
   # choose bright-green handle pixels, excluding translucent big panel via very high green chroma
   b=(im[:,:,1]>200)&(im[:,:,0]<100)&(im[:,:,2]<100)&(D<3); yy,xx=np.where(b)
   if c in ['left','right']: b &= (np.indices(mask.shape)[1]>130)&(np.indices(mask.shape)[1]<195)&(np.indices(mask.shape)[0]>35)&(np.indices(mask.shape)[0]<120)
   if c=='top': b &= (np.indices(mask.shape)[0]>90)&(np.indices(mask.shape)[0]<130)
   yy,xx=np.where(b); print(' bright',len(xx),(int(np.median(xx)),int(np.median(yy))) if len(xx) else None)
   K=np.array(m['cameras'][c]['intrinsic_cv']);C=np.array(m['cameras'][c]['cam2world_gl']);d=D[ys,xs];P=np.stack([(xs-K[0,2])*d/K[0,0],-(ys-K[1,2])*d/K[1,1],-d,np.ones(len(xs))],1)@C.T
   print(' world median all green',np.median(P[:,:3],axis=0).round(3))
